41	    socket.on("connect", () => socket.write(`${JSON.stringify(request)}\n`));
42	    socket.on("data", () => finish(true));
43	    socket.on("end", () => finish(false));
44	    timeout = setTimeout(() => finish(false), timeoutMs);
